// Some portions generated by Claude
package org.eclipse.rdf4j.federated;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.util.Repositories;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * The magic-property syntax of the set-returning extension functions must be rewritten by the federation's own
 * optimizer pipeline instead of being treated as a statement pattern that no member can answer.
 */
public class MagicPropertyTests extends SPARQLBaseTest {

	@BeforeEach
	public void prepareData() throws Exception {
		prepareTest(Arrays.asList("/tests/data/data1.ttl", "/tests/data/data2.ttl"));
	}

	@Test
	public void generateSeriesWithoutMembers() {
		assertThat(column("SELECT ?n WHERE { (1 3) <http://rdf4j.org/function/array#generateSeries> ?n } ORDER BY ?n",
				"n")).containsExactly("1", "2", "3");
	}

	@Test
	public void splitJoinedWithFederatedPattern() {
		assertThat(column("SELECT ?age ?part WHERE { <http://namespace1.org/Person_1> foaf:age ?age ."
				+ " (\"a,b\" \",\") <http://rdf4j.org/function/string#split> ?part } ORDER BY ?part", "part"))
						.containsExactly("a", "b");
	}

	private List<String> column(String query, String name) {
		String prefixes = "PREFIX foaf: <http://xmlns.com/foaf/0.1/>\n";
		List<BindingSet> rows = Repositories.tupleQueryNoTransaction(this.fedxRule.repository, prefixes + query,
				it -> QueryResults.asList(it));
		List<String> values = new ArrayList<>();
		for (BindingSet row : rows) {
			values.add(row.getValue(name).stringValue());
		}
		return values;
	}
}
